    display: flex;
    gap: 0;
    min-height: 600px;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    overflow: hidden;
    background: #fff;
}

/* Sidebar */
::deep .settings-sidebar {
    width: 220px;
    min-width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1rem 0;
}

::deep .sidebar-title {
    padding: 0 1.25rem 0.75rem;
    margin-bottom: 0.5rem;
    border-bottom: 1px solid #dee2e6;
    font-weight: 600;
    color: #495057;
}

