::deep .avatar-preview {
    width: 100px;
    height: 100px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #dee2e6;
}

::deep .avatar-area {
    display: flex;
    align-items: flex-start;
    gap: 1.5rem;
}

/* Appearance preview */
::deep .live-preview {
    border: 1px solid #dee2e6;
    border-radius: 8px;
    overflow: hidden;
    transition: all 0.3s ease;
}

::deep .preview-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #dee2e6;
}

::deep .preview-body {
    padding: 1rem;
}

::deep .preview-theme-light {
    background: #ffffff;
    color: #212529;
}

::deep .preview-theme-light .preview-header {
    background: #f8f9fa;
}

::deep .preview-theme-dark {
    background: #1e1e2e;
    color: #cdd6f4;
    border-color: #45475a;
}

::deep .preview-theme-dark .preview-header {
    background: #313244;
    border-color: #45475a;
}

::deep .preview-theme-system {
    background: linear-gradient(135deg, #ffffff 50%, #1e1e2e 50%);
    color: #212529;
}

::deep .preview-theme-system .preview-header {
    background: #e9ecef;
}

::deep .preview-font-small {
    font-size: 0.8rem;
}

::deep .preview-font-medium {
    font-size: 1rem;
}

::deep .preview-font-large {
    font-size: 1.2rem;
}

::deep .preview-compact .preview-header,
::deep .preview-compact .preview-body {
    padding: 0.4rem 0.75rem;
}

::deep .preview-compact p {
    margin-bottom: 0.25rem;
}

/* Password panel */
::deep .password-form {
    max-width: 400px;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
    border: 1px solid #dee2e6;
}

/* Success toast animation */
::deep .fade-in {
    animation: fadeIn 0.3s ease-in;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-5px); }
    to { opacity: 1; transform: translateY(0); }
}

/* Modal backdrop fix */
::deep .modal-backdrop {
    position: fixed;
    inset: 0;
    z-index: 1040;
}

::deep .modal.d-block {
    position: fixed;
    inset: 0;
    z-index: 1050;
    display: flex !important;
    align-items: center;
    justify-content: center;
}

