@page "/settings"
@namespace sv_d85a34a7ec4147699cfe8dd19a7247a0.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection"
                     OnSectionSelected="section => _activeSection = section" />

    <div class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </div>
</div>

.settings-dashboard {
    display: flex;
    gap: 0;
    min-height: 600px;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    overflow: hidden;
    background: #fff;
}

/* Sidebar */
::deep .settings-sidebar {
    width: 220px;
    min-width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1rem 0;
}

::deep .sidebar-title {
    padding: 0 1.25rem 0.75rem;
    margin-bottom: 0.5rem;
    border-bottom: 1px solid #dee2e6;
    font-weight: 600;
    color: #495057;
}

::deep .settings-sidebar .nav-link {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.6rem 1.25rem;
    color: #495057;
    border: none;
    background: none;
    width: 100%;
    text-align: left;
    font-size: 0.95rem;
    cursor: pointer;
    transition: background-color 0.15s, color 0.15s;
    border-left: 3px solid transparent;
}

::deep .settings-sidebar .nav-link:hover {
    background: #e9ecef;
    color: #212529;
}

::deep .settings-sidebar .nav-link.active {
    background: #e7f1ff;
    color: #0d6efd;
    font-weight: 600;
    border-left-color: #0d6efd;
}

::deep .section-icon {
    font-size: 1.1rem;
}

/* Content area */
.settings-content {
    flex: 1;
    padding: 1.5rem 2rem;
    overflow-y: auto;
}

::deep .settings-section h3 {
    margin-bottom: 1.25rem;
    padding-bottom: 0.75rem;
    border-bottom: 2px solid #e9ecef;
    color: #212529;
}

/* Profile */
::deep .avatar-preview {
    width: 100px;
    height: 100px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #dee2e6;
}

::deep .avatar-area {
    display: flex;
    align-items: flex-start;
    gap: 1.5rem;
}

/* Appearance preview */
::deep .live-preview {
    border: 1px solid #dee2e6;
    border-radius: 8px;
    overflow: hidden;
    transition: all 0.3s ease;
}

::deep .preview-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #dee2e6;
}

::deep .preview-body {
    padding: 1rem;
}

::deep .preview-theme-light {
    background: #ffffff;
    color: #212529;
}

::deep .preview-theme-light .preview-header {
    background: #f8f9fa;
}

::deep .preview-theme-dark {
    background: #1e1e2e;
    color: #cdd6f4;
    border-color: #45475a;
}

::deep .preview-theme-dark .preview-header {
    background: #313244;
    border-color: #45475a;
}

::deep .preview-theme-system {
    background: linear-gradient(135deg, #ffffff 50%, #1e1e2e 50%);
